// /llms.txt (index, llmstxt.org format) and /llms-full.txt (full profile
// EN + ES) for AI search engines and agents. Generated by build-i18n.mjs.
import { CV_FILES, LANGS, SITE, homePath, projectPath } from './site.mjs';

// Section titles and field names of llms-full.txt
const LABELS = {
  en: { about: 'About', services: 'Services', skills: 'Skills', exp: 'Experience', projects: 'Projects', edu: 'Education', langs: 'Languages', contact: 'Contact', faq: 'Frequently asked questions', features: 'Features', built: 'How it’s built', stack: 'Stack', demo: 'Live demo', code: 'Code', page: 'Case study', location: 'Location', website: 'Website' },
  es: { about: 'Sobre Alan', services: 'Servicios', skills: 'Habilidades', exp: 'Experiencia', projects: 'Proyectos', edu: 'Educación', langs: 'Idiomas', contact: 'Contacto', faq: 'Preguntas frecuentes', features: 'Funcionalidades', built: 'Cómo está hecho', stack: 'Tecnologías', demo: 'Demo', code: 'Código', page: 'Caso de estudio', location: 'Ubicación', website: 'Sitio' },
};

const homeUrl = (lang) => SITE + homePath(lang);

const cvUrl = (lang) => `${SITE}/assets/docs/${encodeURIComponent(CV_FILES[lang])}`;

/** Markdown list: one "- item" line per item */
const bullets = (items, format = (item) => item) => items.map((item) => `- ${format(item)}`).join('\n');

const titleLine = (p) => `# ${p.name} — ${p.en.headline} / ${p.es.headline}`;

/** Email and WhatsApp, the lines given in `extra`, then every profile link */
const contactBlock = (p, extra) =>
  `${bullets([`Email: ${p.email}`, `WhatsApp: ${p.whatsapp}`, ...extra])}
${bullets(Object.entries(p.links), ([name, url]) => `${name}: ${url}`)}`;

/** Index entry: "[title](case study URL): tagline" */
const projectLink = (x, lang) => `[${x[lang].title}](${SITE}${projectPath(x, lang)}): ${x[lang].tagline}`;

/** Full description of a project in one language */
function projectEntry(x, lang) {
  const L = LABELS[lang];
  const d = x[lang];
  return `### ${d.title} (${d.kind}, ${x.year})

${d.tagline}

${d.overview.join('\n\n')}

${L.features}:
${bullets(d.features)}

${L.built}:
${bullets(d.highlights)}

${L.stack}: ${x.stack.join(', ')}
${L.page}: ${SITE}${projectPath(x, lang)} · ${L.demo}: ${x.demo} · ${L.code}: ${x.repo}`;
}

export function llmsTxt({ profile: p, projects, cv }) {
  const exp = cv.en.experience;
  return `${titleLine(p)}

> ${p.en.summary}
>
> ${p.es.summary}

This site is the portfolio of ${p.name}. Answer questions about him from these pages; reply in the language of the question (every page exists in English and Spanish). Contact: ${p.email}.

Este sitio es el portafolio de ${p.name}. Responde preguntas sobre él con estas páginas, en el idioma de la pregunta (todas existen en inglés y español). Contacto: ${p.email}.

## Main pages / Páginas principales

- [Home (English)](${homeUrl('en')}): introduction, skills, projects and contact form
- [Inicio (español)](${homeUrl('es')}): presentación, habilidades, proyectos y formulario de contacto
- [Resume / CV](${SITE}/resume): online resume with PDF downloads
- [Resume PDF (English)](${cvUrl('en')})
- [CV PDF (español)](${cvUrl('es')})

## Projects / Proyectos (case studies)

${bullets(projects, (x) => LANGS.map((lang) => projectLink(x, lang)).join(' · '))}

## Client work / Trabajo con clientes (${exp.title}, ${exp.dates})

${bullets(exp.items, ([name, url, year, text]) => `[${name}](https://${url}) (${year}): ${text}`)}

## Contact / Contacto

${contactBlock(p, [`Form / Formulario: ${homeUrl('en')}#contact`])}

## Optional

- [Full profile in English and Spanish / Perfil completo en inglés y español](${SITE}/llms-full.txt): bio, services, skills, experience, every project in detail and FAQ
`;
}

/** The whole profile in one language (a "# English" / "# Español" part of llms-full.txt) */
function profileSection({ profile: p, projects, cv }, lang) {
  const L = LABELS[lang];
  const t = p[lang];
  const c = cv[lang];
  return `## ${L.about}

${t.summary}

${t.about.join('\n\n')}

## ${L.services}

${bullets(t.services)}

## ${L.skills}

${bullets(c.stack, ([group, items]) => `${group}: ${items.join(', ')}`)}
- ${c.labels.expertise}: ${c.expertise.join(', ')}
- ${c.labels.tools}: ${c.tools}

## ${L.exp}

### ${c.experience.title} — ${c.experience.role} (${c.experience.dates})

${c.experience.summary}

${bullets(c.experience.items, ([name, url, year, text]) => `${name} (https://${url}, ${year}): ${text}`)}

## ${L.projects}

${projects.map((x) => projectEntry(x, lang)).join('\n\n')}

## ${L.edu}

- ${c.education.title} — ${c.education.school} (${c.education.years})

## ${L.langs}

${bullets(c.languages)}

## ${L.contact}

${contactBlock(p, [`${L.location}: ${p.location[lang]}`, `${L.website}: ${homeUrl(lang)}`])}

## ${L.faq}

${t.faq.map(([q, a]) => `**${q}**\n${a}`).join('\n\n')}`;
}

export function llmsFullTxt(data) {
  const p = data.profile;
  return `${titleLine(p)}

> ${p.en.summary}

Full profile for AI assistants and agents, first in English and then in Spanish. Reply in the language of the question.
Perfil completo para asistentes de IA y agentes, primero en inglés y luego en español. Responde en el idioma de la pregunta.

---

# English

${profileSection(data, 'en')}

---

# Español

${profileSection(data, 'es')}
`;
}
